func cmdEvaluateSupplier(ctx *kotodama.AppContext, body []byte) ([]byte, error) {
	var args struct {
		VendorID string `json:"vendor_id"`; Name string `json:"name"`
		Category string `json:"category"`; RiskLevel string `json:"risk_level"`
		Certifications []string `json:"certifications"`
		LeadTimeDays int `json:"lead_time_days"`; MinOrderQty float64 `json:"min_order_qty"`
	}
	json.Unmarshal(body, &args)
	if args.VendorID == "" || args.Name == "" { return json.Marshal(map[string]any{"error": "vendor_id and name required"}) }
	if args.RiskLevel == "" { args.RiskLevel = "unassessed" }
	certsJSON, _ := json.Marshal(args.Certifications)
	err := kotodama.Q("unispsc_suppliers").Insert(kotodama.Row{
		"vendor_id": args.VendorID, "name": args.Name, "category": args.Category,
		"risk_level": args.RiskLevel, "certifications": string(certsJSON),
		"lead_time_days": args.LeadTimeDays, "min_order_qty": args.MinOrderQty,
		"org_id": ctx.OrgID, "user_id": ctx.UserID, "actor_id": ctx.UserID,
	})
	if err != nil { return nil, err }
	kotodama.G("UNSPSCVendor").Merge(kotodama.Eq{"vendor_id": args.VendorID}).Set(kotodama.Row{"name": args.Name, "risk_level": args.RiskLevel}).Exec()
	kotodama.G("UNSPSCVendor").Match(kotodama.Eq{"vendor_id": args.VendorID}).Edge("SUPPLIES", nil, "UNSPSCProduct", kotodama.Eq{"code": commodityCode}).Set(kotodama.Row{}).Exec()
