func initSchema() {
	kotodama.Q("").Exec(`CREATE TABLE IF NOT EXISTS unispsc_specs (
		id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '',
		manufacturer TEXT NOT NULL DEFAULT '', model_number TEXT NOT NULL DEFAULT '',
		attributes TEXT NOT NULL DEFAULT '{}',
		org_id TEXT NOT NULL DEFAULT 'anon', user_id TEXT NOT NULL DEFAULT 'anon', actor_id TEXT NOT NULL DEFAULT ''
	)`)
	kotodama.Q("").Exec(`CREATE TABLE IF NOT EXISTS unispsc_procurements (
		id TEXT PRIMARY KEY, fiscal_year TEXT NOT NULL DEFAULT '',
		buyer_org TEXT NOT NULL DEFAULT '', supplier_org TEXT NOT NULL DEFAULT '',
		procurement_stage TEXT NOT NULL DEFAULT '', value REAL NOT NULL DEFAULT 0,
		currency TEXT NOT NULL DEFAULT 'USD', quantity REAL NOT NULL DEFAULT 0,
		unit TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '',
		org_id TEXT NOT NULL DEFAULT 'anon', user_id TEXT NOT NULL DEFAULT 'anon', actor_id TEXT NOT NULL DEFAULT ''
	)`)
	kotodama.Q("").Exec(`CREATE TABLE IF NOT EXISTS unispsc_suppliers (
		vendor_id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT '',
		risk_level TEXT NOT NULL DEFAULT 'unassessed', certifications TEXT NOT NULL DEFAULT '[]',
		lead_time_days INTEGER NOT NULL DEFAULT 0, min_order_qty REAL NOT NULL DEFAULT 0,
		last_assessed TEXT NOT NULL DEFAULT '', contract_expires TEXT NOT NULL DEFAULT '',
		org_id TEXT NOT NULL DEFAULT 'anon', user_id TEXT NOT NULL DEFAULT 'anon', actor_id TEXT NOT NULL DEFAULT ''
	)`)
	kotodama.Q("").Exec(`CREATE TABLE IF NOT EXISTS unispsc_standards (
		id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '',
		status TEXT NOT NULL DEFAULT 'current', mandatory_jurisdictions TEXT NOT NULL DEFAULT '[]',
		description TEXT NOT NULL DEFAULT '',
		org_id TEXT NOT NULL DEFAULT 'anon', user_id TEXT NOT NULL DEFAULT 'anon', actor_id TEXT NOT NULL DEFAULT ''
	)`)
	kotodama.Q("").Exec(`CREATE TABLE IF NOT EXISTS unispsc_risks (
		id TEXT PRIMARY KEY, threat TEXT NOT NULL DEFAULT '', probability REAL NOT NULL DEFAULT 0,
		impact REAL NOT NULL DEFAULT 0, severity TEXT NOT NULL DEFAULT 'medium',
		status TEXT NOT NULL DEFAULT 'open', mitigation TEXT NOT NULL DEFAULT '',
		org_id TEXT NOT NULL DEFAULT 'anon', user_id TEXT NOT NULL DEFAULT 'anon', actor_id TEXT NOT NULL DEFAULT ''
	)`)

	kotodama.G("UNSPSCProduct").Merge(kotodama.Eq{"code": commodityCode}).Set(kotodama.Row{
		"name": commodityName, "segment": segmentCode, "family": familyCode,
		"class": classCode, "level": "commodity",
	}).Exec()
}

func handleWCommit(commit kotodama.WCommit) error {
	if commit.Action != "create" {
		return nil
	}
	return nil
}

func cmdGetSpec(ctx *kotodama.AppContext, body []byte) ([]byte, error) {
	var args struct {
		ID string `json:"id"`
	}
	json.Unmarshal(body, &args)
	if args.ID != "" {
		r, err := kotodama.Q("unispsc_specs").Where(kotodama.Eq{"id": args.ID}).Query()
		if err != nil {
			return nil, err
		}
		return []byte(r), nil
	}
	r, err := kotodama.Q("unispsc_specs").Limit(50).Query()
	if err != nil {
		return nil, err
	}
	return []byte(r), nil
}

func cmdSearchVariants(ctx *kotodama.AppContext, body []byte) ([]byte, error) {
	var args struct {
		Query string `json:"query"`
		Limit int    `json:"limit"`
	}
	json.Unmarshal(body, &args)
	if args.Limit == 0 {
		args.Limit = 50
	}
	r, err := kotodama.Q("unispsc_specs").WhereLike("name", "%"+args.Query+"%").Limit(uint64(args.Limit)).Query()
	if err != nil {
		return nil, err
	}
	return []byte(r), nil
}

func cmdGetConcordance(ctx *kotodama.AppContext, body []byte) ([]byte, error) {
	r, err := kotodama.G("UNSPSCProduct").Match(kotodama.Eq{"code": commodityCode}).EdgeMatch("UNSPSC_CPC_MAP", nil, "CPCProduct", nil).Return("cpc_code", "relationship").Query()
	if err != nil {
		return nil, err
	}
	return []byte(r), nil
}

func cmdEvaluateSupplier(ctx *kotodama.AppContext, body []byte) ([]byte, error) {
	var args struct {
		VendorID       string   `json:"vendor_id"`
		Name           string   `json:"name"`
		Category       string   `json:"category"`
		RiskLevel      string   `json:"risk_level"`
		Certifications []string `json:"certifications"`
		LeadTimeDays   int      `json:"lead_time_days"`
		MinOrderQty    float64  `json:"min_order_qty"`
	}
	json.Unmarshal(body, &args)
	if args.VendorID == "" || args.Name == "" {
		return json.Marshal(map[string]any{"error": "vendor_id and name required"})
	}
	if args.RiskLevel == "" {
		args.RiskLevel = "unassessed"
	}
	certsJSON, _ := json.Marshal(args.Certifications)
	err := kotodama.Q("unispsc_suppliers").Insert(kotodama.Row{
		"vendor_id": args.VendorID, "name": args.Name, "category": args.Category,
		"risk_level": args.RiskLevel, "certifications": string(certsJSON),
		"lead_time_days": args.LeadTimeDays, "min_order_qty": args.MinOrderQty,
		"org_id": ctx.OrgID, "user_id": ctx.UserID, "actor_id": ctx.UserID,
	})
	if err != nil {
		return nil, err
	}
	kotodama.G("UNSPSCVendor").Merge(kotodama.Eq{"vendor_id": args.VendorID}).Set(kotodama.Row{
		"name": args.Name, "risk_level": args.RiskLevel,
	}).Exec()
	kotodama.G("UNSPSCVendor").Match(kotodama.Eq{"vendor_id": args.VendorID}).
		Edge("SUPPLIES", nil, "UNSPSCProduct", kotodama.Eq{"code": commodityCode}).Set(kotodama.Row{}).Exec()
	return json.Marshal(map[string]any{"ok": true, "vendor_id": args.VendorID})
}

func cmdGenerateRFP(ctx *kotodama.AppContext, body []byte) ([]byte, error) {
	var args struct {
		Title    string  `json:"title"`
		Quantity float64 `json:"quantity"`
		Unit     string  `json:"unit"`
		Budget   float64 `json:"budget"`
		Currency string  `json:"currency"`
		Deadline string  `json:"deadline"`
	}
	json.Unmarshal(body, &args)
	if args.Currency == "" {
		args.Currency = "USD"
	}
	rfp := map[string]any{
		"commodity_code": commodityCode,
		"commodity_name": commodityName,
		"title":          args.Title,
		"quantity":       args.Quantity,
		"unit":           args.Unit,
		"budget":         args.Budget,
		"currency":       args.Currency,
		"deadline":       args.Deadline,
		"segment":        segmentCode,
		"family":         familyCode,
		"class":          classCode,
	}
	payload, _ := json.Marshal(map[string]any{
		"content_type": "application/vnd.etzhayyim.card.rfp",
		"payload":      rfp,
	})
	kotodama.WSend(wChannelFeed, "unispsc.rfp.generated", payload, "application/vnd.etzhayyim.card.rfp", nil, nil)
	return json.Marshal(rfp)
}

func cmdRecordProcurement(ctx *kotodama.AppContext, body []byte) ([]byte, error) {
	var args struct {
		ID               string  `json:"id"`
		FiscalYear       string  `json:"fiscal_year"`
		BuyerOrg         string  `json:"buyer_org"`
		SupplierOrg      string  `json:"supplier_org"`
		ProcurementStage string  `json:"procurement_stage"`
		Value            float64 `json:"value"`
		Currency         string  `json:"currency"`
		Quantity         float64 `json:"quantity"`
		Unit             string  `json:"unit"`
		Country          string  `json:"country"`
	}
	json.Unmarshal(body, &args)
	if args.ID == "" {
		return json.Marshal(map[string]any{"error": "id required"})
	}
	if args.Currency == "" {
		args.Currency = "USD"
	}
	err := kotodama.Q("unispsc_procurements").Insert(kotodama.Row{
		"id": args.ID, "fiscal_year": args.FiscalYear,
		"buyer_org": args.BuyerOrg, "supplier_org": args.SupplierOrg,
		"procurement_stage": args.ProcurementStage, "value": args.Value,
		"currency": args.Currency, "quantity": args.Quantity, "unit": args.Unit,
		"country": args.Country,
		"org_id": ctx.OrgID, "user_id": ctx.UserID, "actor_id": ctx.UserID,
	})
	if err != nil {
		return nil, err
	}
	kotodama.G("Organization").Match(kotodama.Eq{"id": args.BuyerOrg}).
		Edge("PROCURES", kotodama.Eq{"stage": args.ProcurementStage}, "UNSPSCProduct", kotodama.Eq{"code": commodityCode}).
		Set(kotodama.Row{"value": args.Value, "fiscal_year": args.FiscalYear}).Exec()
	return json.Marshal(map[string]any{"ok": true, "id": args.ID})
}

func cmdGetStandards(ctx *kotodama.AppContext, body []byte) ([]byte, error) {
	r, err := kotodama.Q("unispsc_standards").Query()
	if err != nil {
		return nil, err
	}
	return []byte(r), nil
}

func cmdAssessRisk(ctx *kotodama.AppContext, body []byte) ([]byte, error) {
	var args struct {
		ID          string  `json:"id"`
		Threat      string  `json:"threat"`
		Probability float64 `json:"probability"`
		Impact      float64 `json:"impact"`
		Severity    string  `json:"severity"`
		Mitigation  string  `json:"mitigation"`
	}
	json.Unmarshal(body, &args)
	if args.ID == "" || args.Threat == "" {
		return json.Marshal(map[string]any{"error": "id and threat required"})
	}
	if args.Severity == "" {
		args.Severity = "medium"
	}
	err := kotodama.Q("unispsc_risks").Insert(kotodama.Row{
		"id": args.ID, "threat": args.Threat, "probability": args.Probability,
		"impact": args.Impact, "severity": args.Severity, "status": "open",
		"mitigation": args.Mitigation,
		"org_id": ctx.OrgID, "user_id": ctx.UserID, "actor_id": ctx.UserID,
	})
	if err != nil {
		return nil, err
	}
	return json.Marshal(map[string]any{"ok": true, "id": args.ID})
}

func cmdGetContractInfo(ctx *kotodama.AppContext, body []byte) ([]byte, error) {
	r, err := kotodama.G("UNSPSCProduct").Match(kotodama.Eq{"code": commodityCode}).EdgeMatch("GOVERNED_BY", nil, "UNSPSCContract", nil).Return("name", "jurisdiction").Query()
	if err != nil {
		return nil, err
	}
	return []byte(r), nil
}
"}

